import { expect, expectStatus, test } from "../../fixtures";

interface DocumentBody {
  id: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  status: string;
}

interface ErrorBody {
  error: { code: string };
}

test.describe("vendor lifecycle", () => {
  test(
    "a certificate whose expiry date could not be read cannot be approved",
    { tag: "@LIF-08" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor with a name unique to this run,
      // uploads an insurance certificate whose expiry text is unreadable, and submits it.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: `Cert Expiry Vendor ${suffix}`,
          category: "services",
          contact_email: `cert-expiry-${suffix}@vendors.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(vendorResponse, 201);

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `certificate-${suffix}.txt`,
            mimeType: "text/plain",
            buffer: Buffer.from("Certificate of insurance. Policy expires: next spring."),
          },
        },
      });
      const document = await expectStatus<DocumentBody>(uploadResponse, 201);

      // Extraction runs asynchronously; wait until the document has been extracted.
      await expect
        .poll(
          async () =>
            (await expectStatus<DocumentBody>(await member.get(`/api/documents/${document.id}`), 200)).status,
          { timeout: 30_000 },
        )
        .toBe("extracted");

      await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      const extraction = await expectStatus<ExtractionBody>(
        await reviewer.get(`/api/documents/${document.id}/extraction`),
        200,
      );
      expect(extraction.status).toBe("pending_review");

      // Act: the reviewer tries to approve the insurance certificate extraction.
      const decisionResponse = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert: approval is refused with the expiry-missing error, and the extraction stays pending.
      const body = await expectStatus<ErrorBody>(decisionResponse, 409);
      expect(body.error.code).toBe("insurance_expiry_missing");

      const after = await expectStatus<ExtractionBody>(
        await reviewer.get(`/api/documents/${document.id}/extraction`),
        200,
      );
      expect(after.status).toBe("pending_review");
    },
  );
});
